 "content": "from collections import defaultdict, deque


def _components(grid, background):
    h, w = len(grid), len(grid[0])
    seen = set()
    out = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == background or (r, c) in seen:
                continue
            color = grid[r][c]
            todo = [(r, c)]
            seen.add((r, c))
            cells = []
            while todo:
                y, x = todo.pop()
                cells.append((y, x))
                for yy, xx in ((y-1, x), (y+1, x), (y, x-1), (y, x+1)):
                    if 0 <= yy < h and 0 <= xx < w and (yy, xx) not in seen and grid[yy][xx] == color:
                        seen.add((yy, xx))
                        todo.append((yy, xx))
            out.append((color, cells))
    return out


def _canonical(cells):
    forms = []
    maps = (lambda r,c:(r,c), lambda r,c:(r,-c), lambda r,c:(-r,c),
            lambda r,c:(-r,-c), lambda r,c:(c,r), lambda r,c:(c,-r),
            lambda r,c:(-c,r), lambda r,c:(-c,-r))
    for f in maps:
        pts = [f(r,c) for r,c in cells]
        mr, mc = min(r for r,c in pts), min(c for r,c in pts)
        forms.append(tuple(sorted((r-mr,c-mc) for r,c in pts)))
    return min(forms)


def _corner_quality(cells):
    rows, cols = defaultdict(int), defaultdict(int)
    for r,c in cells:
        rows[r] += 1
        cols[c] += 1
    # Coverage by the best crossing row and column; an L-shaped key is almost
    # entirely accounted for by its two arms.
    best = 0
    for r, nr in rows.items():
        for c, nc in cols.items():
            if (r,c) in cells:
                best = max(best, nr + nc - 1)
    rs = [r for r,c in cells]
    cs = [c for r,c in cells]
    height, width = max(rs)-min(rs)+1, max(cs)-min(cs)+1
    return best / len(cells), height, width


def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = defaultdict(int)
    for row in grid:
        for value in row:
            counts[value] += 1
    background = max(counts, key=counts.get)
    comps = _components(grid, background)

    # The large, sparse orthogonal corner is the color key.
    keys = []
    for color, cells in comps:
        quality, height, width = _corner_quality(cells)
        if min(height, width) >= 3 and quality >= 0.82:
            keys.append((len(cells) * quality, color, cells))
    if not keys:
        return [row[:] for row in grid]
    _, key_color, key_cells = max(keys, key=lambda x: x[0])
    kr = sum(r for r,c in key_cells) / len(key_cells)
    kc = sum(c for r,c in key_cells) / len(key_cells)

    # Repeated silhouettes encode the same object in different colors/places.
    groups = defaultdict(list)
    for color, cells in comps:
        if cells != key_cells:
            groups[_canonical(cells)].append((color, cells))
    repeated = [items for items in groups.values() if len(items) >= 2]
    if repeated:
        # Prefer the largest repeated silhouette; within it recolor the copy
        # farthest from the corner key.
        group = max(repeated, key=lambda items: (len(items[0][1]), len(items)))
        target_color, target_cells = max(
            group,
            key=lambda item: (sum((r-kr)**2 + (c-kc)**2 for r,c in item[1]) / len(item[1]))
        )
    else:
        # Some instances provide no exact duplicate: use the largest substantial
        # non-key object farthest from the key.
        candidates = [(color, cells) for color, cells in comps if cells != key_cells and len(cells) >= 3]
        if not candidates:
            return [row[:] for row in grid]
        target_color, target_cells = max(
            candidates,
            key=lambda item: (sum((r-kr)**2 + (c-kc)**2 for r,c in item[1]) / len(item[1]), len(item[1]))
        )

    out = [row[:] for row in grid]
    for r,c in target_cells:
        out[r][c] = key_color
    return out
